{"packet_id":"D069-01","doc_id":"D069","jurisdiction":"NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"FAIR Act ban on algorithmic rent-setting and coordinating functions","requirement":"The FAIR Act makes it unlawful for rental property owners or their agents to use a coordinator's services, for coordinators to facilitate rental price coordination, and for any person to perform a coordinating function that sets or recommends rents using competitors' information.","key_value":null,"coverage_conditions":"Rental property owners, their agents, representatives and subcontractors, coordinators and any person; residential dwelling units intended as primary residences, excluding inpatient medical, licensed long-term care, and detention or correctional facilities.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All residential dwelling units in New Jersey intended as primary residences; institutional and correctional facilities excluded"},"exemptions":"Coordinating function excludes research, statistical analysis or testing, free public rent estimates, real estate brokerage databases available on equal terms to subscribers, and government affordability controls; spreadsheets without artificial intelligence needing human analysis and query-only databases are not algorithmic devices.","penalty":"A violation of section 4 is also a violation of the New Jersey Antitrust Act, and sections 6 through 17 of P.L.1970, c.73 apply to it.","effective_date":"2027-07-01","citation":"P.L. 2026, c.043 § 4","quoted_span":"It shall be unlawful and a violation of the “New Jersey Antitrust Act,” P.L.1970, c.73 (C.56:9-1 et seq.) for: a. a rental property owner, or any agent, representative, or subcontractor thereof, to receive, subscribe to, contract for, or otherwise exchange any form of consideration in return for the use of, the services of a coordinator;","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D069-01","doc_id":"D069","jurisdiction":"NJ","category":"algorithmic_rent_setting","lifecycle":"enacted","title":"FAIR Act preemption of conflicting municipal ordinances","requirement":"A New Jersey municipality may not enact an ordinance that conflicts with the FAIR Act, but nothing in this subsection prohibits ordinances explicitly authorized or required by other law.","key_value":null,"coverage_conditions":"Ordinances of New Jersey municipalities.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Municipal ordinances in New Jersey"},"exemptions":"Ordinances explicitly authorized or required by any other law.","penalty":null,"effective_date":"2027-07-01","citation":"P.L. 2026, c.043 § 6","quoted_span":"A municipality shall be prohibited from enacting an ordinance that conflicts with this act.  This subsection shall not be construed to prohibit the enactment of ordinances explicitly authorized or required by any other law.","interaction":"Preempts local ordinances that conflict with the FAIR Act; ordinances authorized by other law are preserved.","confidence":0.9,"conflict_flag":false,"conflict_note":null}
